import{_ as l,a0 as n,w as p,s as o,I as a,x as e,a1 as i,A as s,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"2018 年 4 個需要關注的人工智能趨勢 | LCTT x X-CMD","titleTemplate":false,"description":"2018 年 4 個需要關注的人工智能趨勢 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"2018 年 4 個需要關注的人工智能趨勢 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"2018 年 4 個需要關注的人工智能趨勢 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20180104 4 artificial intelligence trends to watch","title":"2018 年 4 個需要關注的人工智能趨勢","tag":"201801","desc":""},"relativePath":"201801/20180104 4 artificial intelligence trends to watch.md","filePath":"[post].md"}'),f={name:"201801/20180104 4 artificial intelligence trends to watch.md"};function m(u,t,T,h,k,x){const r=n("Link");return p(),o("div",null,[t[18]||(t[18]=a("h1",{id:"_2018-年-4-個需要關注的人工智能趨勢",tabindex:"-1"},[e("2018 年 4 個需要關注的人工智能趨勢 "),a("a",{class:"header-anchor",href:"#_2018-年-4-個需要關注的人工智能趨勢","aria-label":"Permalink to “2018 年 4 個需要關注的人工智能趨勢”"},"​")],-1)),t[19]||(t[19]=a("blockquote",null,[a("p",null,"今年人工智能決策將變得更加透明？")],-1)),t[20]||(t[20]=a("p",null,[a("img",{src:"https://enterprisersproject.com/sites/default/files/styles/620x350/public/images/CIO%20Mentor.png?itok=K-6s_q2C",alt:""})],-1)),a("p",null,[t[2]||(t[2]=e("無論你的 IT 業務現在使用了多少",-1)),i(r,{href:"https://enterprisersproject.com/tags/artificial-intelligence"},{default:s(()=>[...t[0]||(t[0]=[e("人工智能",-1)])]),_:1}),t[3]||(t[3]=e("，預計你將會在 2018 年使用更多。即便你從來沒有涉獵過 AI 項目，這也可能是將談論轉變為行動的一年，",-1)),i(r,{href:"https://www2.deloitte.com/us/en.html"},{default:s(()=>[...t[1]||(t[1]=[e("德勤",-1)])]),_:1}),t[4]||(t[4]=e("董事總經理 David Schatsky 説。他説：“與 AI 開展合作的公司數量正在上升。”",-1))]),t[21]||(t[21]=d('<p>看看他對未來一年的AI預測：</p><h3 id="_1、預期更多的企業-ai-試點項目" tabindex="-1">1、預期更多的企業 AI 試點項目 <a class="header-anchor" href="#_1、預期更多的企業-ai-試點項目" aria-label="Permalink to “1、預期更多的企業 AI 試點項目”">​</a></h3><p>如今我們經常使用的許多現成的應用程序和平台都將 AI 結合在一起。 Schatsky 説：“除此之外，越來越多的公司正在試驗機器學習或自然語言處理來解決特定的問題，或者幫助理解他們的數據，或者使內部流程自動化，或者改進他們自己的產品和服務。</p><p>“除此之外，公司與人工智能的合作強度將會上升。”他説，“早期採納它的公司已經有五個或略少的項目正在進行中，但是我們認為這個數字會上升到十個或有更多正在進行的計劃。” 他説，這個預測的一個原因是人工智能技術正在變得越來越好，也越來越容易使用。</p><h3 id="_2、人工智能將緩解數據科學人才緊缺的現狀" tabindex="-1">2、人工智能將緩解數據科學人才緊缺的現狀 <a class="header-anchor" href="#_2、人工智能將緩解數據科學人才緊缺的現狀" aria-label="Permalink to “2、人工智能將緩解數據科學人才緊缺的現狀”">​</a></h3><p>人才是數據科學中的一個大問題，大多數大公司都在努力聘用他們所需要的數據科學家。 Schatsky 説，AI 可以承擔一些負擔。他説：“數據科學的實踐，逐漸成為由創業公司和大型成熟的技術供應商提供的自動化的工具。”他解釋説，大量的數據科學工作是重複的、乏味的，自動化的時機已經成熟。 “數據科學家不會消亡，但他們將會獲得更高的生產力，所以一家只能做一些數據科學項目而沒有自動化的公司將能夠使用自動化來做更多的事情，雖然它不能僱用更多的數據科學家”。</p><h3 id="_3、合成數據模型將緩解瓶頸" tabindex="-1">3、合成數據模型將緩解瓶頸 <a class="header-anchor" href="#_3、合成數據模型將緩解瓶頸" aria-label="Permalink to “3、合成數據模型將緩解瓶頸”">​</a></h3><p>Schatsky 指出，在你訓練機器學習模型之前，你必須得到數據來訓練它。 這並不容易，他説：“這通常是一個商業瓶頸，而不是生產瓶頸。 在某些情況下，由於有關健康記錄和財務信息的規定，你無法獲取數據。”</p><p>他説，合成數據模型可以採集一小部分數據，並用它來生成可能需要的較大集合。 “如果你以前需要 10000 個數據點來訓練一個模型，但是隻能得到 2000 個，那麼現在就可以產生缺少的 8000 個數據點，然後繼續訓練你的模型。”</p><h3 id="_4、人工智能決策將變得更加透明" tabindex="-1">4、人工智能決策將變得更加透明 <a class="header-anchor" href="#_4、人工智能決策將變得更加透明" aria-label="Permalink to “4、人工智能決策將變得更加透明”">​</a></h3><p>AI 的業務問題之一就是它經常作為一個黑匣子來操作。也就是説，一旦你訓練了一個模型，它就會吐出你不能解釋的答案。 Schatsky 説：“機器學習可以自動發現人類無法看到的數據模式，因為數據太多或太複雜。 “發現了這些模式後，它可以預測未見的新數據。”</p><p>問題是，有時你確實需要知道 AI 發現或預測背後的原因。 “以醫學圖像為例子來説，模型説根據你給我的數據，這個圖像中有 90％ 的可能性是腫瘤。 “Schatsky 説，“你説，‘你為什麼這麼認為？’ 模型説：‘我不知道，這是數據給的建議。’”</p><p>Schatsky 説，如果你遵循這些數據，你將不得不對患者進行探查手術。 當你無法解釋為什麼時，這是一個艱難的請求。 “但在很多情況下，即使模型產生了非常準確的結果，如果不能解釋為什麼，也沒有人願意相信它。”</p><p>還有一些情況是由於規定，你確實不能使用你無法解釋的數據。 Schatsky 説：“如果一家銀行拒絕貸款申請，就需要能夠解釋為什麼。 這是一個法規，至少在美國是這樣。傳統上來説，人類分銷商會打個電話做回訪。一個機器學習模式可能會更準確，但如果不能解釋它的答案，就不能使用。”</p><p>大多數算法不是為了解釋他們的推理而設計的。 他説：“所以研究人員正在找到聰明的方法來讓 AI 泄漏秘密，並解釋哪些變量使得這個病人更可能患有腫瘤。 一旦他們這樣做，人們可以發現答案，看看為什麼會有這樣的結論。”</p><p>他説，這意味着人工智能的發現和決定可以用在許多今天不可能的領域。 “這將使這些模型更加值得信賴，在商業世界中更具可用性。”</p><hr>',17)),a("p",null,[t[6]||(t[6]=e("via: ",-1)),i(r,{href:"https://enterprisersproject.com/article/2018/1/4-ai-trends-watch"},{default:s(()=>[...t[5]||(t[5]=[e("https://enterprisersproject.com/article/2018/1/4-ai-trends-watch",-1)])]),_:1})]),a("p",null,[t[10]||(t[10]=e("作者：",-1)),i(r,{href:"https://enterprisersproject.com/user/minda-zetlin"},{default:s(()=>[...t[7]||(t[7]=[e("Minda Zetlin",-1)])]),_:1}),t[11]||(t[11]=e(" 譯者：",-1)),i(r,{href:"https://github.com/Wuod3n"},{default:s(()=>[...t[8]||(t[8]=[e("Wuod3n",-1)])]),_:1}),t[12]||(t[12]=e(" 校對：",-1)),i(r,{href:"https://github.com/wxy"},{default:s(()=>[...t[9]||(t[9]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[15]||(t[15]=e("本文由 ",-1)),i(r,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原創編譯，",-1)),i(r,{href:"https://linux.cn/"},{default:s(()=>[...t[14]||(t[14]=[e("Linux中國",-1)])]),_:1}),t[17]||(t[17]=e(" 榮譽推出",-1))])])}const I=l(f,[["render",m]]);export{b as __pageData,I as default};
